$nvmeDrives = Get-CimInstance Win32_DiskDrive | Where-Object { $_.InterfaceType -eq "NVMe" } | Select-Object -ExpandProperty PNPDeviceID

 foreach ($nvme in $nvmeDrives) {
  $msiKey = "HKLM:\SYSTEM\CurrentControlSet\Enum\$nvme\Device Parameters\Interrupt Management\MessageSignaledInterruptProperties"
  if (Test-Path $msiKey) {
  Set-ItemProperty -Path $msiKey -Name "MSISupported" -Value 1
  }

  $affinityKey = "HKLM:\SYSTEM\CurrentControlSet\Enum\$nvme\Device Parameters\Interrupt Management\Affinity Policy"
  if (Test-Path $affinityKey) {
  Set-ItemProperty -Path $affinityKey -Name "DevicePriority" -Value 0
  }
 }

